TEST_SOURCES['test_autopilot_value_governor'] = "from federation.autopilot_suites_v1.autopilot_value_governor import *\ndef obs(**kw):\n d=dict(automation_id='A',mission_id='M',material_progress=True,calls=2,latency_s=10,owner_minutes_saved=10,false_alerts=0,duplicate_work=0,cost_units=.1,outcome_value=5); d.update(kw); return RunObservation(**d)\ndef test_hold_for_data(): assert AutopilotValueGovernor().evaluate('A').recommendation=='HOLD_FOR_DATA'\ndef test_promote():\n g=AutopilotValueGovernor(); [g.record(obs()) for _ in range(3)]; assert g.evaluate('A').recommendation=='PROMOTE'\ndef test_suspend():\n g=AutopilotValueGovernor(); [g.record(obs(material_progress=False,outcome_value=0,owner_minutes_saved=0,calls=20,cost_units=3)) for _ in range(4)]; assert g.evaluate('A').recommendation=='SUSPEND'\ndef test_backoff_false_alerts():\n g=AutopilotValueGovernor(); [g.record(obs(false_alerts=1,outcome_value=1)) for _ in range(3)]; assert g.evaluate('A').recommendation=='BACKOFF'\ndef test_overlap(): assert AutopilotValueGovernor.overlap_score({'a','b'},{'b','a'})==1\ndef test_merge_candidate(): assert AutopilotValueGovernor().merge_candidate('a','b',{'x','y'},{'x','y'})\ndef test_persistence(tmp_path):\n p=tmp_path/'v.json'; g=AutopilotValueGovernor(p); g.record(obs()); assert len(AutopilotValueGovernor(p).rows)==1\ndef test_invalid_observation():\n try:AutopilotValueGovernor().record(obs(calls=-1)); assert False\n except ValueError:pass\n"

