TEST_SOURCES['test_event_wake_mesh'] = "from datetime import datetime,timezone,timedelta\nfrom federation.autopilot_suites_v1.event_wake_mesh import *\ndef e(**kw):\n d=dict(event_id='E1',source='github',event_type='CI_DONE',subject='pr:1',occurred_at='2026-09-05T00:00:00+00:00'); d.update(kw); return EventEnvelope(**d)\ndef test_match():\n m=EventWakeMesh(); m.register(Subscription('S','M',sources=('github',),event_types=('CI_DONE',))); assert m.ingest(e()).matched_missions==('M',)\ndef test_dedupe():\n m=EventWakeMesh(); m.register(Subscription('S','M')); m.ingest(e()); assert m.ingest(e()).duplicate_suppressed\ndef test_materiality():\n m=EventWakeMesh(); m.register(Subscription('S','M',min_materiality=.8)); assert not m.ingest(e(materiality=.2)).matched_missions\ndef test_labels():\n m=EventWakeMesh(); m.register(Subscription('S','M',required_labels=('legal',))); assert m.ingest(e(labels=('legal',))).matched_missions\ndef test_subject_filter():\n m=EventWakeMesh(); m.register(Subscription('S','M',subjects=('x',))); assert not m.ingest(e()).matched_missions\ndef test_debounce():\n m=EventWakeMesh(); m.register(Subscription('S','M',debounce_seconds=60)); now=datetime.now(timezone.utc); m.ingest(e(event_id='1'),now); r=m.ingest(e(event_id='2'),now+timedelta(seconds=10)); assert r.debounce_suppressed==('S',)\ndef test_invalidation_keys(): assert 'subject:pr:1' in EventWakeMesh().ingest(e()).invalidation_keys\ndef test_collision():\n m=EventWakeMesh(); m.register(Subscription('S','M'))\n try:m.register(Subscription('S','X')); assert False\n except ValueError:pass\n"

TEST_SOURCES['test_external_wait_state_machine'] = "from datetime import datetime,timezone,timedelta\nfrom federation.autopilot_suites_v1.external_wait_state_machine import *\ndef test_wait_resume():\n s=ExternalWaitStateMachine(); s.wait('M',WaitCondition('WAITING_FOR_CI','run','done')); assert s.on_event({'wait_state':'WAITING_FOR_CI','key':'run','value':'done','event_id':'E'})==('M',)\ndef test_wrong_value():\n s=ExternalWaitStateMachine(); s.wait('M',WaitCondition('WAITING_FOR_CI','run','done')); assert not s.on_event({'wait_state':'WAITING_FOR_CI','key':'run','value':'bad'})\ndef test_invalid_state():\n try:ExternalWaitStateMachine().wait('M',WaitCondition('WAITING_FOR_MAGIC','x')); assert False\n except ValueError:pass\ndef test_complete_terminal():\n s=ExternalWaitStateMachine(); s.complete('M')\n try:s.wait('M',WaitCondition('WAITING_FOR_CI','x')); assert False\n except ValueError:pass\ndef test_cancel(): s=ExternalWaitStateMachine(); s.cancel('M'); assert s.missions['M'].state=='CANCELLED'\ndef test_timeout():\n now=datetime.now(timezone.utc); s=ExternalWaitStateMachine(); s.wait('M',WaitCondition('WAITING_FOR_CI','x',expires_at=(now-timedelta(seconds=1)).isoformat())); assert s.timeout(now)==('M',)\ndef test_not_before():\n now=datetime.now(timezone.utc); s=ExternalWaitStateMachine(); s.wait('M',WaitCondition('WAITING_FOR_CI','x',not_before=(now+timedelta(hours=1)).isoformat())); assert not s.on_event({'wait_state':'WAITING_FOR_CI','key':'x'},now)\ndef test_resume_count():\n s=ExternalWaitStateMachine(); s.wait('M',WaitCondition('WAITING_FOR_CI','x')); s.on_event({'wait_state':'WAITING_FOR_CI','key':'x'}); assert s.missions['M'].resume_count==1\n"

