TEST_SOURCES['test_persistent_mission_sandbox'] = "from datetime import datetime,timezone,timedelta\nfrom federation.autopilot_suites_v1.persistent_mission_sandbox import *\ndef test_put_read(tmp_path):\n s=PersistentMissionSandbox(tmp_path,'M'); s.put_text('a.txt','hi'); assert s.read_text('a.txt')=='hi'\ndef test_hash(tmp_path):\n s=PersistentMissionSandbox(tmp_path,'M'); h=s.put_text('a','x'); assert h==s.file_hash('a')\ndef test_checkpoint_restore(tmp_path):\n s=PersistentMissionSandbox(tmp_path,'M'); s.put_text('a','one'); s.checkpoint('c'); s.put_text('a','two'); s.restore('c'); assert s.read_text('a')=='one'\ndef test_path_traversal(tmp_path):\n s=PersistentMissionSandbox(tmp_path,'M')\n try:s.put_text('../x','bad'); assert False\n except ValueError:pass\ndef test_quota(tmp_path):\n s=PersistentMissionSandbox(tmp_path,'M',max_bytes=2)\n try:s.put_text('a','123'); assert False\n except ValueError:pass\ndef test_list(tmp_path):\n s=PersistentMissionSandbox(tmp_path,'M'); s.put_text('b/a','x'); assert s.list_files()==('b/a',)\ndef test_expiry(tmp_path):\n s=PersistentMissionSandbox(tmp_path,'M',ttl_seconds=1); future=datetime.now(timezone.utc)+timedelta(seconds=2); assert s.expired(future)\ndef test_cleanup(tmp_path):\n s=PersistentMissionSandbox(tmp_path,'M',ttl_seconds=1); future=datetime.now(timezone.utc)+timedelta(seconds=2); assert s.cleanup_if_expired(future)\n"

TEST_SOURCES['test_scoped_auto_approval_memory'] = "from datetime import datetime,timezone,timedelta\nfrom federation.autopilot_suites_v1.scoped_auto_approval_memory import *\ndef grant(**kw):\n d=dict(grant_id='G',mission_id='M',effect_classes=('REVERSIBLE_INTERNAL',),target_patterns=('drafts/*',),authorization_ref='AUTH',max_uses=2); d.update(kw); return ApprovalGrant(**d)\ndef req(**kw):\n d=dict(mission_id='M',effect_class='REVERSIBLE_INTERNAL',target='drafts/a',reversible=True,readback_available=True); d.update(kw); return ApprovalRequest(**d)\ndef test_authorize(tmp_path):\n s=ScopedApprovalMemory(tmp_path/'a.json'); s.add(grant()); assert s.authorize(req()).allowed\ndef test_wrong_target(tmp_path):\n s=ScopedApprovalMemory(tmp_path/'a.json'); s.add(grant()); assert not s.authorize(req(target='prod/a')).allowed\ndef test_usage_limit(tmp_path):\n s=ScopedApprovalMemory(tmp_path/'a.json'); s.add(grant(max_uses=1)); assert s.authorize(req()).allowed; assert not s.authorize(req()).allowed\ndef test_revoke(tmp_path):\n s=ScopedApprovalMemory(tmp_path/'a.json'); s.add(grant()); s.revoke('G'); assert not s.authorize(req()).allowed\ndef test_expired(tmp_path):\n s=ScopedApprovalMemory(tmp_path/'a.json'); s.add(grant(expires_at=(datetime.now(timezone.utc)-timedelta(seconds=1)).isoformat())); assert not s.authorize(req()).allowed\ndef test_requires_reversible(tmp_path):\n s=ScopedApprovalMemory(tmp_path/'a.json'); s.add(grant()); assert not s.authorize(req(reversible=False)).allowed\ndef test_requires_readback(tmp_path):\n s=ScopedApprovalMemory(tmp_path/'a.json'); s.add(grant()); assert not s.authorize(req(readback_available=False)).allowed\ndef test_collision(tmp_path):\n s=ScopedApprovalMemory(tmp_path/'a.json'); s.add(grant())\n try:s.add(grant(mission_id='X')); assert False\n except ValueError:pass\n"

TEST_SOURCES['test_trigger_recovery_reflexes'] = "from federation.autopilot_suites_v1.trigger_recovery_reflexes import *\ndef sig(**kw):\n d=dict(signal_id='S',trigger_type='CI_FAIL',fingerprint='DEPENDENCY:PY',route_id='R'); d.update(kw); return FailureSignal(**d)\ndef test_default_reflex(): assert TriggerRecoveryReflexes.defaults().decide(sig()).reflex_id=='REFLEX-CI-DEPENDENCY'\ndef test_no_match(): assert TriggerRecoveryReflexes.defaults().decide(sig(trigger_type='X')).state=='NO_REFLEX'\ndef test_effect_hold(): assert TriggerRecoveryReflexes.defaults().decide(sig(effect_class='HIGH_CONSEQUENCE')).state=='HELD_EFFECT_CLASS'\ndef test_changed_route_required_after_repeat():\n e=TriggerRecoveryReflexes.defaults(); e.decide(sig(signal_id='1')); assert e.decide(sig(signal_id='2')).require_changed_route\ndef test_circuit_opens():\n e=TriggerRecoveryReflexes.defaults(); r=None\n for i in range(3):r=e.decide(sig(signal_id=str(i)))\n assert r.circuit_open\ndef test_repeat_reflex_immediate_open(): assert TriggerRecoveryReflexes.defaults().decide(sig(trigger_type='REPEATED_FAILURE',fingerprint='X')).circuit_open\ndef test_register_collision():\n e=TriggerRecoveryReflexes(); d=ReflexDefinition('R','X','*',('A',)); e.register(d)\n try:e.register(ReflexDefinition('R','Y','*',('B',))); assert False\n except ValueError:pass\ndef test_actions_nonempty(): assert TriggerRecoveryReflexes.defaults().decide(sig()).actions\n"

CASES = []
for module_name, source in TEST_SOURCES.items():
    namespace = {"__name__": f"_autopilot_court_{module_name}"}
    exec(compile(source, f"<{module_name}>", "exec"), namespace)
    for name, fn in sorted(namespace.items()):
        if name.startswith("test_") and callable(fn):
            CASES.append(pytest.param(fn, id=f"{module_name}::{name}"))

assert len(CASES) == 93, f"expected 93 local-qualified cases, found {len(CASES)}"

@pytest.mark.parametrize("case", CASES)
def test_federation_autopilot_suites_v1(case):
    import inspect
    import tempfile
    from pathlib import Path
    params = inspect.signature(case).parameters
    if "tmp_path" in params:
        with tempfile.TemporaryDirectory(prefix="autopilot-suite-court-") as d:
            case(Path(d))
    else:
        case()
